from fastapi import FastAPI, Query
from fastapi.testclient import TestClient
from typing import List, Sequence

app = FastAPI()

@app.get("/list")
def read_list(q: list[int] | None = Query(None)):
    return {"q": q}

@app.get("/sequence")
def read_sequence(q: Sequence[int] | None = Query(None)):
    return {"q": q}

client = TestClient(app)

def test_list_none():
    response = client.get("/list")
    print(f"List None: {response.json()}")
    assert response.json() == {"q": None}

def test_list_values():
    response = client.get("/list", params={"q": [1, 2]})
    print(f"List Values: {response.json()}")
    assert response.json() == {"q": [1, 2]}

def test_sequence_none():
    response = client.get("/sequence")
    print(f"Sequence None: {response.json()}")
    assert response.json() == {"q": None}

def test_sequence_values():
    response = client.get("/sequence", params={"q": [1, 2]})
    print(f"Sequence Values: {response.json()}")
    assert response.json() == {"q": [1, 2]}

try:
    test_list_none()
    test_list_values()
    test_sequence_none()
    test_sequence_values()
    print("All tests passed!")
except Exception as e:
    print(f"Test failed: {e}")
